using System;
using System.Collections.Generic;
using UnityEngine;

namespace RTXMnesia.Player
{
    /// <summary>
    /// Generated by HandsConverter (ignored Resources/HplHands.prefab): the player's hands (models/player/hands/
    /// hands.ent, its legacy clips named as in the .ent) and the hand objects (models/hand_objects/*/*.ho), each an
    /// entity built like map entities (model, lights, billboards). Values are the files' (HPL units, degrees).
    /// </summary>
    public sealed class HplHandsData : MonoBehaviour
    {
        public const string ResourceName = "HplHands";

        [Tooltip("The hands entity (cLuxPlayerHands::mpHandsEntity).")]
        public Transform hands;
        public Animation handsAnimation;

        [Serializable]
        public class HandObject
        {
            public string name, type;
            public Transform entity;
            // iLuxHandObject::LoadSettings
            public Vector3 offsetScale = Vector3.one, offsetRotation, offsetPosition;
            public string animIdle = "", animDraw = "", animHolster = "", attachBone = "attachpoint";
            // cLuxHandObject_LightSource::LoadImplementedVars
            public float fadeInTime, fadeOutTime;
            public bool hasSwayPhysics;
            public float maxSwayVel, swayGravity, swayFriction, swayPlayerSpeedMul, swayCameraRollMul;
            public Vector2 swayAngleLimits, swayDownAngleLimits;
            public Vector3 swayPinDir = Vector3.one;
            public string skipSwaySubMesh = "";
        }

        public List<HandObject> handObjects = new();
    }
}
